package com.styleshop.product.repository;
import com.styleshop.product.mapper.ProductMapper; import com.styleshop.product.model.Product; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; import java.math.BigDecimal; import java.util.Optional;
@Repository @ConditionalOnProperty(name="styleshop.product-dao",havingValue="mybatis",matchIfMissing=true) public class MyBatisProductDataSource implements ProductDataSource {private final ProductMapper mapper;public MyBatisProductDataSource(ProductMapper m){mapper=m;}public Page<Product> search(String k,Long c,BigDecimal min,BigDecimal max,Pageable p){String sort=p.getSort().stream().findFirst().map(o->o.getProperty()).orElse("id");String dir=p.getSort().stream().findFirst().map(o->o.getDirection().name()).orElse("ASC");var list=mapper.search(k,c,min,max,sort,dir,p.getPageSize(),p.getOffset());return new PageImpl<>(list,p,mapper.count(k,c,min,max));}public Optional<Product> findById(Long id){return Optional.ofNullable(mapper.findById(id));}public Product save(Product p){if(p.getId()==null)mapper.insert(p);else mapper.update(p);return p;}public void deleteById(Long id){mapper.deleteById(id);}public String name(){return "MYBATIS";}}
